const reducedMotionQuery=window.matchMedia('(prefers-reduced-motion:reduce)');const finePointerQuery=window.matchMedia('(hover:hover)and(pointer:fine)');window.addEventListener('load',()=>{const loader=document.querySelector('.page-loader');if(!loader)return;const delay=reducedMotionQuery.matches?0:180;window.setTimeout(()=>{loader.classList.add('hidden');},delay);});document.addEventListener('DOMContentLoaded',()=>{const prefersReducedMotion=reducedMotionQuery.matches;const canUsePointerEffects=finePointerQuery.matches&&!prefersReducedMotion;const navbar=document.getElementById('navbar');const hamburger=document.getElementById('hamburger');const navLinks=document.getElementById('nav-links');const handleScroll=()=>{if(!navbar)return;navbar.classList.toggle('scrolled',window.scrollY>32);};handleScroll();window.addEventListener('scroll',handleScroll,{passive:true});if(hamburger&&navLinks){const setMenuState=(isOpen)=>{hamburger.classList.toggle('active',isOpen);navLinks.classList.toggle('active',isOpen);hamburger.setAttribute('aria-expanded',String(isOpen));hamburger.setAttribute('aria-label',isOpen?'Fermer le menu':'Ouvrir le menu');};hamburger.addEventListener('click',()=>{setMenuState(!hamburger.classList.contains('active'));});navLinks.querySelectorAll('a').forEach((link)=>{link.addEventListener('click',()=>setMenuState(false));});document.addEventListener('click',(event)=>{if(!hamburger.contains(event.target)&&!navLinks.contains(event.target)){setMenuState(false);}});document.addEventListener('keydown',(event)=>{if(event.key==='Escape'){setMenuState(false);hamburger.focus();}});}const hero=document.querySelector('.hero');if(canUsePointerEffects){const cursorLight=document.createElement('div');cursorLight.className='cursor-light';document.body.appendChild(cursorLight);document.addEventListener('pointermove',(event)=>{cursorLight.style.transform=`translate3d(${event.clientX-220}px,${event.clientY-220}px,0)`;cursorLight.classList.add('is-visible');},{passive:true});document.addEventListener('pointerleave',()=>{cursorLight.classList.remove('is-visible');});}if(canUsePointerEffects&&hero){const heroMedia=hero.querySelectorAll('video,.hero-video,.hero-media,.hero-visual,.hero-image');let targetX=0;let targetY=0;let parallaxFrame=null;const renderHeroParallax=()=>{hero.style.setProperty('--hero-parallax-x',`${targetX}px`);hero.style.setProperty('--hero-parallax-y',`${targetY}px`);heroMedia.forEach((element)=>{element.style.transform=`translate3d(${targetX}px,${targetY}px,0)`;});parallaxFrame=null;};hero.addEventListener('pointermove',(event)=>{const rect=hero.getBoundingClientRect();const progressX=(event.clientX-rect.left)/rect.width-0.5;const progressY=(event.clientY-rect.top)/rect.height-0.5;targetX=Math.max(-10,Math.min(10,progressX*20));targetY=Math.max(-8,Math.min(8,progressY*16));if(!parallaxFrame)parallaxFrame=window.requestAnimationFrame(renderHeroParallax);},{passive:true});hero.addEventListener('pointerleave',()=>{targetX=0;targetY=0;if(!parallaxFrame)parallaxFrame=window.requestAnimationFrame(renderHeroParallax);});}const counters=document.querySelectorAll('.counter');const animateCounter=(counter)=>{const target=Number.parseInt(counter.getAttribute('data-target')||counter.textContent||'0',10);if(!Number.isFinite(target))return;if(prefersReducedMotion){counter.textContent=String(target);return;}const duration=1300;const startTime=performance.now();const update=(currentTime)=>{const progress=Math.min((currentTime-startTime)/duration,1);const eased=1-Math.pow(1-progress,3);counter.textContent=String(Math.round(target*eased));if(progress<1){window.requestAnimationFrame(update);}else{counter.textContent=String(target);}};window.requestAnimationFrame(update);};if(counters.length>0){const counterObserver=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting||entry.target.classList.contains('counted'))return;entry.target.classList.add('counted');animateCounter(entry.target);counterObserver.unobserve(entry.target);});},{threshold:0.5});counters.forEach((counter)=>counterObserver.observe(counter));}if(canUsePointerEffects){document.querySelectorAll('.btn,.btn-whatsapp-nav').forEach((button)=>{button.classList.add('magnetic-ready');button.addEventListener('pointermove',(event)=>{const rect=button.getBoundingClientRect();const offsetX=event.clientX-(rect.left+rect.width/2);const offsetY=event.clientY-(rect.top+rect.height/2);const x=Math.max(-10,Math.min(10,offsetX*0.16));const y=Math.max(-8,Math.min(8,offsetY*0.16));button.style.setProperty('--magnet-x',`${x}px`);button.style.setProperty('--magnet-y',`${y}px`);button.style.setProperty('--magnet-scale','1.02');},{passive:true});button.addEventListener('pointerleave',()=>{button.style.setProperty('--magnet-x','0px');button.style.setProperty('--magnet-y','0px');button.style.setProperty('--magnet-scale','1');});});}document.querySelectorAll('.faq-item').forEach((details)=>{const summary=details.querySelector('summary');if(!summary||details.querySelector('.faq-panel'))return;const panel=document.createElement('div');const inner=document.createElement('div');panel.className='faq-panel';inner.className='faq-panel-inner';while(summary.nextSibling){inner.appendChild(summary.nextSibling);}panel.appendChild(inner);details.appendChild(panel);summary.addEventListener('click',(event)=>{if(prefersReducedMotion)return;event.preventDefault();details.classList.add('is-animating');if(details.open){panel.style.height=`${panel.scrollHeight}px`;panel.style.opacity='1';window.requestAnimationFrame(()=>{panel.style.height='0px';panel.style.opacity='0';});const finishClose=(transitionEvent)=>{if(transitionEvent.target!==panel)return;details.open=false;details.classList.remove('is-animating');panel.removeEventListener('transitionend',finishClose);};panel.addEventListener('transitionend',finishClose);return;}details.open=true;panel.style.height='0px';panel.style.opacity='0';window.requestAnimationFrame(()=>{panel.style.height=`${panel.scrollHeight}px`;panel.style.opacity='1';});const finishOpen=(transitionEvent)=>{if(transitionEvent.target!==panel)return;panel.style.height='auto';details.classList.remove('is-animating');panel.removeEventListener('transitionend',finishOpen);};panel.addEventListener('transitionend',finishOpen);});});const contactForm=document.getElementById('contact-form');const formMessage=document.getElementById('form-message');const submitBtn=document.getElementById('submit-btn');if(contactForm&&formMessage&&submitBtn){const btnText=submitBtn.querySelector('.btn-text');const btnLoader=submitBtn.querySelector('.btn-loader');contactForm.addEventListener('submit',async(event)=>{event.preventDefault();if(btnText)btnText.style.display='none';if(btnLoader)btnLoader.style.display='inline-flex';submitBtn.disabled=true;formMessage.className='form-message';formMessage.textContent='';try{const response=await fetch('https://api.web3forms.com/submit',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(contactForm)))});const result=await response.json();if(!result.success)throw new Error(result.message||'Erreur lors de l\'envoi');formMessage.className='form-message success';formMessage.textContent='Message envoye avec succes. Je vous repondrai rapidement.';contactForm.reset();}catch{formMessage.className='form-message error';formMessage.textContent='Erreur lors de l\'envoi. Vous pouvez aussi me contacter sur WhatsApp.';}finally{if(btnText)btnText.style.display='inline';if(btnLoader)btnLoader.style.display='none';submitBtn.disabled=false;}});}document.querySelectorAll('.share-copy').forEach((button)=>{button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(window.location.href);button.classList.add('copied');button.setAttribute('aria-label','Lien copie');window.setTimeout(()=>{button.classList.remove('copied');button.setAttribute('aria-label','Copier le lien');},1600);}catch{button.setAttribute('aria-label','Copie indisponible');}});});const readingProgress=document.getElementById('reading-progress');if(readingProgress){const updateReadingProgress=()=>{const article=document.querySelector('.article');if(!article)return;const start=article.offsetTop;const end=start+article.offsetHeight-window.innerHeight;const current=window.scrollY;const progress=end<=start?100:((current-start)/(end-start))*100;readingProgress.style.width=`${Math.max(0,Math.min(100,progress))}%`;};updateReadingProgress();window.addEventListener('scroll',updateReadingProgress,{passive:true});window.addEventListener('resize',updateReadingProgress);}});
